SELECT * FROM acc_satisfaction_collection_task
WHERE tenant_id = #{query.tenantId}
  AND deleted = b'0'
  AND project_id IN

    #{projectId}


  AND assigned_to_user_id = #{query.assignedToUserId}

ORDER BY project_id, task_revision_no DESC, id DESC

SELECT *
FROM acc_satisfaction_collection_task
WHERE tenant_id = #{query.tenantId}
  AND project_task_id = #{query.projectTaskId}
  AND trigger_owner_context = #{query.triggerOwnerContext}
  AND trigger_object_type = #{query.triggerObjectType}
  AND trigger_fact_id = #{query.triggerFactId}
  AND trigger_fact_version = #{query.triggerFactVersion}
  AND deleted = b'0'
FOR UPDATE

mapper.update:
UPDATE acc_satisfaction_collection_task
   SET task_status='PENDING_DECISION', version=version+1,
       updater=#{query.updater}, update_time=NOW(3)
 WHERE tenant_id=#{query.tenantId} AND id=#{query.taskId}
   AND task_status IN ('PENDING_COLLECTION','ASSIGNED') AND version=#{query.expectedVersion}

UPDATE acc_satisfaction_collection_task
   SET task_status=#{query.targetStatus}, result_id=#{query.resultId}, version=version+1,
       updater=#{query.updater}, update_time=NOW(3)
 WHERE tenant_id=#{query.tenantId} AND id=#{query.taskId}
   AND task_status='PENDING_DECISION' AND result_id IS NULL AND version=#{query.expectedVersion}
